import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

class AnotherClass {
    private List<String> anotherList;

    public AnotherClass(List<String> inputList) {
        List<String> localList = inputList; // This is a local variable declaration, not a field assignment to a field
        if (localList != null) {
            anotherList = localList; // This is a field assignment, but the right-hand side is a local variable, not a parameter
        }
    }
}
